properties.setup:
// R3F owns the renderer; use its canvas document for this scene's HUD/input.
const document = context.three.gl.domElement.ownerDocument;
const window = document.defaultView;
state.keys = {}; state.started = false; state.score = 0; state.passed = 0; state.missed = 0; state.speed = 0; state.message = 'ENTER TO LAUNCH'; state.messageTime = 0;
const hud = document.createElement('div');
context.onCleanup(() => hud.remove());
hud.style.cssText = 'position:fixed;left:28px;right:28px;top:82px;bottom:28px;pointer-events:none;z-index:50;color:#e6f7f3;font-family:system-ui,sans-serif';
hud.innerHTML = '<div style="display:flex;justify-content:space-between;gap:20px"><div style="background:#102936e8;padding:18px 24px;border-left:3px solid #63f4dd"><div style="font-size:11px;letter-spacing:4px;color:#63f4dd">KESTREL / FLIGHT TRIALS</div><div style="font-size:30px;font-weight:800;letter-spacing:6px;margin-top:4px">SKYWARD</div></div><div data-stats style="background:#102936e8;padding:18px 24px;font-size:14px;line-height:1.8;text-align:right;font-variant-numeric:tabular-nums"></div></div><div data-message style="position:absolute;top:38%;width:100%;text-align:center;font-size:26px;font-weight:700;letter-spacing:3px;text-shadow:0 2px 15px #102936"></div><div style="position:absolute;bottom:0;left:0;background:#102936e8;padding:15px 22px;border-left:3px solid #ff7048;font-size:12px;letter-spacing:1px">W / S · CLIMB / DIVE &nbsp;&nbsp; A / D · BANK &nbsp;&nbsp; SHIFT · BOOST &nbsp;&nbsp; R · RESTART<br><span style="color:#8eb7bd;font-size:11px;line-height:2">FLY THROUGH 12 MINT GATES · ARROW KEYS ALSO WORK</span></div>';
document.body.appendChild(hud); state.hud = hud; state.stats = hud.querySelector('[data-stats]'); state.banner = hud.querySelector('[data-message]');
const down = e => { if (/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)) return; if (['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space','Enter'].includes(e.code)) e.preventDefault(); state.keys[e.code] = true; if(e.code==='Enter' && state.messageTime<900) state.started=true; if(e.code==='KeyR') state.restart=true; };
const up = e => {state.keys[e.code]=false;}; const blur = () => {state.keys={};};
for (const [type, handler] of [['keydown', down], ['keyup', up], ['blur', blur]]) {
  window.addEventListener(type, handler);
  context.onCleanup(() => window.removeEventListener(type, handler));
}

properties.update:
if (!state.hud) return;
const dt=Math.min(context.delta,.05); const get=id => context.prefab.getObject(id);
const gates=Array.from({length:8},(_,i)=>get('gate-'+i));
if(state.restart){ object.position.set(0,35,30); object.rotation.set(0,0,0); state.started=false; state.score=0;state.passed=0;state.missed=0;state.speed=0;state.sequence=8;state.messageTime=0;state.restart=false; gates.forEach((g,i)=>{if(g)g.position.set(Math.sin(i*.7)*26,35+Math.sin(i*.8)*12,-100-i*145);}); for(let i=0;i<30;i++){const o=get('island-'+i);if(o)o.position.z=-70-i*95;}for(let i=0;i<14;i++){const o=get('cloud-'+i);if(o)o.position.z=-i*210;} }
state.sequence ??= 8;
const k=state.keys, boost=k.ShiftLeft||k.ShiftRight, horizontal=(k.KeyD||k.ArrowRight?1:0)-(k.KeyA||k.ArrowLeft?1:0),vertical=(k.KeyW||k.ArrowUp?1:0)-(k.KeyS||k.ArrowDown?1:0);
if(state.started){
state.speed += ((boost?85:46)-state.speed)*Math.min(1,dt*2);
object.position.z -= state.speed*dt;object.position.x=Math.max(-85,Math.min(85,object.position.x+horizontal*32*dt));object.position.y=Math.max(1,Math.min(115,object.position.y+vertical*25*dt));
object.rotation.z += (-horizontal*.55-object.rotation.z)*Math.min(1,dt*5);object.rotation.x += (vertical*.2-object.rotation.x)*Math.min(1,dt*4);object.rotation.y += (-horizontal*.12-object.rotation.y)*Math.min(1,dt*4);
if(object.position.y<3){state.started=false;state.message='SPLASHDOWN — R TO RESTART';state.messageTime=999;}
for(const g of gates){if(g && object.position.z<g.position.z){const hit=Math.hypot(object.position.x-g.position.x,object.position.y-g.position.y)<11.5;if(hit){state.passed++;state.score+=boost?150:100;state.message=state.passed>=12?'TRIAL COMPLETE · KEEP FLYING':'GATE CLEARED +'+(boost?150:100);}else{state.missed++;state.message='GATE MISSED';}state.messageTime=1.4;const i=state.sequence++;g.position.set(Math.sin(i*.7)*26,35+Math.sin(i*.8)*12,-100-i*145);}}
for(let i=0;i<30;i++){const o=get('island-'+i);if(o&&o.position.z>object.position.z+100)o.position.z-=2850;}
for(let i=0;i<14;i++){const o=get('cloud-'+i);if(o&&o.position.z>object.position.z+100)o.position.z-=2940;}
}
const sea=get('sea'),sky=get('sky');if(sea)sea.position.z=object.position.z-600;if(sky)sky.position.z=object.position.z;
for(const id of ['flame-left','flame-right']){const f=get(id);if(f)f.scale.y=state.started?(boost?1.8:1):.3;}
state.messageTime=Math.max(0,state.messageTime-dt);
state.stats.textContent='SPEED '+Math.round(state.speed*3.6)+' KM/H  ·  ALT '+Math.round(object.position.y)+' M | GATES '+state.passed+'/12  ·  SCORE '+state.score;
state.banner.textContent=state.messageTime>0?state.message:!state.started?'ENTER TO LAUNCH':'';
